-- Production: port 3010, http://10.10.4.165:9000/middleware  (edit before applying)
UPDATE public.sap_middleware_config
SET connection_mode = 'proxy',
    deployment_mode = 'self_hosted',
    middleware_port = 3002,
    middleware_url  = 'http://10.10.4.165:8081/middleware',
    updated_at      = now();

INSERT INTO public.sap_middleware_config (connection_mode, deployment_mode, middleware_port, middleware_url)
SELECT 'proxy', 'self_hosted', 3002, 'http://10.10.4.165:8081/middleware'
WHERE NOT EXISTS (SELECT 1 FROM public.sap_middleware_config);

-- Link the table mapping to the endpoint by name.
UPDATE public.sap_table_mappings m
SET endpoint_id = e.id
FROM public.sap_endpoints e
WHERE e.name = m.api_name;

COMMIT;
